    if (!document.querySelector(selector)) return;

    for (const root of document.querySelectorAll(selector)) {

        if (root.dataset.revisionToolsState !== 'ready') root.dataset.revisionToolsState = 'loading';

    }

    if (document.querySelector('[data-revision-editor-context]') && document.querySelector('[data-paper-editor][x-ignore]')) return;

    let revisionTools;

    try {

        revisionTools = await import('./revision-workspace');

    } catch {

        for (const root of document.querySelectorAll(selector)) {

            root.dataset.revisionToolsState = 'failed';

            showRevisionToolsNotice(root, 'Revision tools could not load. Reload this page before submitting.');

        }

        window.frameElement?.dispatchEvent(new Event('revision-editor-error'));

        return;

    }

    revisionTools.default(confirmSubmission);

    for (const root of document.querySelectorAll(selector)) {

        root.dataset.revisionToolsState = 'ready';

    }

}



